/**
 * طابور مزامنة قسم الصيانة عند إلغاء تأجيل المزامنة / عودة الاتصال.
 */
import { db } from '@/firebase';
import {
  addDoc,
  collection,
  deleteDoc,
  deleteField,
  doc,
  getDocs,
  limit,
  query,
  serverTimestamp,
  setDoc,
  updateDoc,
  where,
} from 'firebase/firestore';
import { isManualFirestoreHoldEffective } from '@/utils/manualFirestoreSyncHold';

/** في الطابور JSON — يُستبدل بـ serverTimestamp عند الرفع */
export const MAINT_SERVER_TS = '__MAINT_SERVER_TS__';
/** يُستبدل بـ deleteField() عند الرفع */
export const MAINT_DELETE_FIELD = '__MAINT_DELETE_FIELD__';

export type MaintenanceQueuedOp =
  | { t: 'itemSet'; id: string; data: Record<string, unknown>; merge: boolean }
  | { t: 'itemUpdate'; id: string; patch: Record<string, unknown> }
  | { t: 'itemDelete'; id: string }
  | { t: 'legacyPendingAdd'; data: Record<string, unknown> }
  | { t: 'legacyDoneAdd'; data: Record<string, unknown> }
  | { t: 'legacyPendingPatchByLinked'; linkedId: string; patch: Record<string, unknown> }
  | { t: 'legacyPendingDeleteByLinked'; linkedId: string }
  | { t: 'legacyDoneDeleteByLinked'; linkedId: string }
  | { t: 'wasteAdd'; uid: string; wid: string; data: Record<string, unknown> }
  | { t: 'materialAdd'; uid: string; mid: string; data: Record<string, unknown> };

export const maintenanceQueueKey = (uid: string) => `maintenance_syncQueue_${uid}`;

export function readMaintenanceQueue(uid: string): MaintenanceQueuedOp[] {
  try {
    const raw = localStorage.getItem(maintenanceQueueKey(uid));
    if (!raw) return [];
    const a = JSON.parse(raw);
    return Array.isArray(a) ? a : [];
  } catch {
    return [];
  }
}

export function appendMaintenanceQueue(uid: string, op: MaintenanceQueuedOp) {
  try {
    const cur = readMaintenanceQueue(uid);
    cur.push(op);
    localStorage.setItem(maintenanceQueueKey(uid), JSON.stringify(cur));
  } catch {
    /* ignore */
  }
}

function applyMarkers(patch: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(patch)) {
    if (v === MAINT_SERVER_TS) (out as Record<string, unknown>)[k] = serverTimestamp();
    else if (v === MAINT_DELETE_FIELD) (out as Record<string, unknown>)[k] = deleteField();
    else if (typeof v === 'string' && k === 'createdAt' && v !== MAINT_SERVER_TS && v !== MAINT_DELETE_FIELD) {
      const d = new Date(v);
      (out as Record<string, unknown>)[k] = Number.isFinite(d.getTime()) ? d : v;
    } else out[k] = v;
  }
  return out;
}

async function deleteLegacyByLinked(linkedId: string, col: 'maintenance_pending' | 'maintenance_done') {
  const q = query(collection(db, col), where('linkedId', '==', linkedId), limit(25));
  const snap = await getDocs(q);
  await Promise.all(snap.docs.map((d) => deleteDoc(d.ref)));
}

export async function flushMaintenanceOfflineQueue(uid: string): Promise<{ ok: number; failed: number }> {
  if (!uid || isManualFirestoreHoldEffective(uid)) return { ok: 0, failed: 0 };
  let ops: MaintenanceQueuedOp[];
  try {
    const raw = localStorage.getItem(maintenanceQueueKey(uid));
    if (!raw) return { ok: 0, failed: 0 };
    ops = JSON.parse(raw);
    if (!Array.isArray(ops) || ops.length === 0) return { ok: 0, failed: 0 };
    localStorage.setItem(maintenanceQueueKey(uid), '[]');
  } catch {
    return { ok: 0, failed: 0 };
  }

  const failed: MaintenanceQueuedOp[] = [];
  let ok = 0;

  for (const op of ops) {
    try {
      switch (op.t) {
        case 'itemSet': {
          const data = applyMarkers({ ...op.data, updatedAt: MAINT_SERVER_TS });
          await setDoc(doc(db, 'maintenance_items', op.id), data, { merge: op.merge });
          break;
        }
        case 'itemUpdate': {
          const patch = applyMarkers({ ...op.patch, updatedAt: MAINT_SERVER_TS });
          await updateDoc(doc(db, 'maintenance_items', op.id), patch);
          break;
        }
        case 'itemDelete': {
          await deleteLegacyByLinked(op.id, 'maintenance_pending');
          await deleteLegacyByLinked(op.id, 'maintenance_done');
          await deleteDoc(doc(db, 'maintenance_items', op.id));
          break;
        }
        case 'legacyPendingAdd': {
          const data = applyMarkers({ ...op.data, createdAt: op.data.createdAt ?? MAINT_SERVER_TS });
          await addDoc(collection(db, 'maintenance_pending'), data);
          break;
        }
        case 'legacyDoneAdd': {
          const base = { ...op.data };
          if (base.completedAt === undefined || base.completedAt === null) base.completedAt = MAINT_SERVER_TS;
          const data = applyMarkers(base);
          await addDoc(collection(db, 'maintenance_done'), data);
          break;
        }
        case 'legacyPendingPatchByLinked': {
          const q = query(collection(db, 'maintenance_pending'), where('linkedId', '==', op.linkedId), limit(1));
          const snap = await getDocs(q);
          if (!snap.empty) {
            await updateDoc(doc(db, 'maintenance_pending', snap.docs[0].id), applyMarkers(op.patch));
          }
          break;
        }
        case 'legacyPendingDeleteByLinked': {
          await deleteLegacyByLinked(op.linkedId, 'maintenance_pending');
          break;
        }
        case 'legacyDoneDeleteByLinked': {
          await deleteLegacyByLinked(op.linkedId, 'maintenance_done');
          break;
        }
        case 'wasteAdd': {
          const data = applyMarkers({ ...op.data, createdAt: MAINT_SERVER_TS });
          await setDoc(doc(db, 'users', op.uid, 'maintenance_waste', op.wid), data);
          break;
        }
        case 'materialAdd': {
          const data = applyMarkers({ ...op.data, createdAt: MAINT_SERVER_TS });
          await setDoc(doc(db, 'users', op.uid, 'maintenance_materials', op.mid), data);
          break;
        }
        default:
          break;
      }
      ok += 1;
    } catch {
      failed.push(op);
    }
  }

  if (failed.length > 0) {
    try {
      const rest = readMaintenanceQueue(uid);
      localStorage.setItem(maintenanceQueueKey(uid), JSON.stringify([...failed, ...rest]));
    } catch {
      /* ignore */
    }
  }

  return { ok, failed: failed.length };
}
