  const revertCompletedToStatus = async (id: string, targetStatus: MaintenanceItemStatus) => {
    try {
      const item = items.find(i => i.id === id);
      if (!item) return;

      // حساب مقدار الكاش الذي أضيف عند الإكمال
      const fullAmount = Math.max(0, Number(item.repairPrice || 0));
      // المبلغ المدفوع مقدماً قبل الإكمال (العربون)
      let deposit = Math.max(0, Number((item as any).partialPaymentBeforeComplete || 0));
      // في السجلات القديمة التي لا تحتوي على الحقل الجديد، نحاول استنتاج العربون من المتبقي
      if (!deposit && typeof item.remainingDue === 'number') {
        const remaining = Math.max(0, Number(item.remainingDue));
        if (fullAmount >= remaining) {
          deposit = fullAmount - remaining;
        }
      }
      let amount = Math.max(0, fullAmount - deposit);
      if (!Number.isFinite(amount) || amount <= 0) {
        // كفالباك أخير فقط إذا لم نستطع حساب العربون
        amount = fullAmount;
      }

      // إعادة حالة المستند في Firestore
      const newPartial = deposit > 0 ? deposit : 0;
      const newRemaining = Math.max(0, Math.round((fullAmount - newPartial) * 100) / 100);

      const revertPatch = {
        status: targetStatus,
        profitAdded: false,
        completedAt: null as null,
        partialPayment: newPartial > 0 ? newPartial : null,
        remainingDue: newRemaining > 0 ? newRemaining : null,
      };

      if (maintenanceHold && user?.uid) {
        appendMaintenanceQueue(user.uid, { t: 'itemUpdate', id, patch: revertPatch });
        const createdMs = item.createdAt instanceof Date ? item.createdAt.getTime() : Date.now();
        upsertMaintenanceHoldBuffer(user.uid, {
          id,
          repairPrice: fullAmount,
          partialPayment: newPartial > 0 ? newPartial : undefined,
          status: targetStatus,
          createdAtMs: createdMs,
          completedAtMs: undefined,
        });

        setItems((prev) => {
          const next = prev.map((i) =>
            i.id === id
              ? {
                  ...i,
                  status: targetStatus,
                  completedAt: undefined,
                  profitAdded: false,
                  partialPayment: newPartial > 0 ? newPartial : undefined,
                  partialPaymentBeforeComplete: newPartial > 0 ? newPartial : undefined,
                  remainingDue: newRemaining > 0 ? newRemaining : undefined,
                }
              : i
          );
          try {
            localStorage.setItem(
              maintenanceItemsCacheKey(user.uid),
              JSON.stringify(serializeMaintenanceItemsForCache(next))
            );
          } catch {
            /* ignore */
          }
          computeProfit(next);
          return next;
        });

        try {
          if (amount > 0) {
            const genericKey = `cashBalance_${user?.uid || 'default'}`;
            const shopKey = `cashBalance_${user?.uid || 'default'}_${shopIdCtx || 'main'}`;
            const saved = localStorage.getItem(shopKey) ?? localStorage.getItem(genericKey) ?? '0';
            const currentCash = parseFloat(saved || '0') || 0;
            const newCash = currentCash - amount;
            try { localStorage.setItem(genericKey, String(newCash)); } catch {}
            try { localStorage.setItem(shopKey, String(newCash)); } catch {}
            try { window.dispatchEvent(new CustomEvent('cashBalanceChanged', { detail: { value: newCash } })); } catch {}
          }
        } catch (cashErr) {
          console.warn('فشل عكس تأثير الكاش عند إرجاع الصيانة:', cashErr);
        }
        return;
      }

      await updateDoc(doc(db, 'maintenance_items', id), revertPatch);

      if (user?.uid && isManualFirestoreHoldEffective(user.uid)) {
        const createdMs =
          item.createdAt instanceof Date ? item.createdAt.getTime() : Date.now();
        upsertMaintenanceHoldBuffer(user.uid, {
          id,
          repairPrice: fullAmount,
          partialPayment: newPartial > 0 ? newPartial : undefined,
          status: targetStatus,
          createdAtMs: createdMs,
          completedAtMs: undefined,
        });
      }

      // تحديث الحالة المحلية
      setItems((prev) => {
        const next = prev.map((i) =>
          i.id === id
            ? {
                ...i,
                status: targetStatus,
                completedAt: undefined,
                profitAdded: false,
                partialPayment: newPartial > 0 ? newPartial : undefined,
                partialPaymentBeforeComplete: newPartial > 0 ? newPartial : undefined,
                remainingDue: newRemaining > 0 ? newRemaining : undefined,
              }
            : i
        );
        try {
          if (user?.uid) {
            localStorage.setItem(
              maintenanceItemsCacheKey(user.uid),
              JSON.stringify(serializeMaintenanceItemsForCache(next))
            );
          }
        } catch {
          /* ignore */
        }
        computeProfit(next);
        return next;
      });

      // عكس تأثير الكاش
      try {
        if (amount > 0) {
          const genericKey = `cashBalance_${user?.uid || 'default'}`;
          const shopKey = `cashBalance_${user?.uid || 'default'}_${shopIdCtx || 'main'}`;
          const saved = localStorage.getItem(shopKey) ?? localStorage.getItem(genericKey) ?? '0';
          const currentCash = parseFloat(saved || '0') || 0;
          const newCash = currentCash - amount;
          try { localStorage.setItem(genericKey, String(newCash)); } catch {}
          try { localStorage.setItem(shopKey, String(newCash)); } catch {}
          if (user?.uid) {
            try { await userDataService.updateUserData(user.uid, { cashBalance: newCash }); } catch {}
          }
          try {
            const shopId = (profile as any)?.shopId || shopIdCtx;
            if (shopId) {
              await updateDoc(doc(db, 'dashboardData', shopId), { cashBalance: newCash, lastUpdated: new Date().toISOString() } as any);
            }
          } catch {}
          try { window.dispatchEvent(new CustomEvent('cashBalanceChanged', { detail: { value: newCash } })); } catch {}
        }
      } catch (cashErr) {
        console.warn('فشل عكس تأثير الكاش عند إرجاع الصيانة:', cashErr);
      }
    } catch (e) {
      console.error('Failed to revert maintenance item:', e);
      alert('حدث خطأ أثناء إرجاع عنصر الصيانة من تم التصليح.');
    } finally {
      setBusyItemId(null);
    }
  };

  const handleRevertClick = async (id: string) => {
    if (busyItemId) return;
    const item = items.find(i => i.id === id);
    if (!item) return;
    setRevertDialogItem(item);
  };

  const removeItem = async (id: string) => {
    if (busyItemId) return;
    const item = items.find(i => i.id === id);
    // في حالة تم التصليح: نحتاج لعكس الجزء الذي أُضيف عند الإكمال فقط (بدون العربون)
    let amountToReverse = 0;
    if (item && item.status === 'completed') {
      try {
        const fullAmount = Math.max(0, Number(item.repairPrice || 0));
        let deposit = Math.max(0, Number((item as any).partialPaymentBeforeComplete || 0));
        if (!deposit && typeof item.remainingDue === 'number') {
          const remaining = Math.max(0, Number(item.remainingDue));
          if (fullAmount >= remaining) {
            deposit = fullAmount - remaining;
          }
        }
        let amt = Math.max(0, fullAmount - deposit);
        if (!Number.isFinite(amt) || amt <= 0) {
          amt = fullAmount;
        }
        amountToReverse = amt;
      } catch (e) {
        console.warn('Failed to compute maintenance delete cash revert amount:', e);
      }
    } else if (item && (item.status === 'in_progress' || item.status === 'waiting_for_delivery')) {
      // في حالة "جاري التصليح" أو "في انتظار التسليم": نرجّع فقط العربون المدفوع مسبقاً
      const deposit = Math.max(0, Number((item as any).partialPayment || 0));
      if (deposit > 0 && Number.isFinite(deposit)) {
        amountToReverse = deposit;
      }
    }
    setBusyItemId(id);
    try {
      if (maintenanceHold && user?.uid) {
        appendMaintenanceQueue(user.uid, { t: 'itemDelete', id });
        removeMaintenanceHoldBufferEntry(user.uid, id);

        setItems((prev) => {
          const next = prev.filter((i) => i.id !== id);
          try {
            localStorage.setItem(
              maintenanceItemsCacheKey(user.uid),
              JSON.stringify(serializeMaintenanceItemsForCache(next))
            );
          } catch {
            /* ignore */
          }
          computeProfit(next);
          return next;
        });

        if (amountToReverse > 0) {
          try {
            const genericKey = `cashBalance_${user?.uid || 'default'}`;
            const shopKey = `cashBalance_${user?.uid || 'default'}_${shopIdCtx || 'main'}`;
            const saved = localStorage.getItem(shopKey) ?? localStorage.getItem(genericKey) ?? '0';
            const currentCash = parseFloat(saved || '0') || 0;
            const newCash = currentCash - amountToReverse;
            try { localStorage.setItem(genericKey, String(newCash)); } catch {}
            try { localStorage.setItem(shopKey, String(newCash)); } catch {}
            try { window.dispatchEvent(new CustomEvent('cashBalanceChanged', { detail: { value: newCash } })); } catch {}
          } catch (cashErr) {
            console.warn('Failed to reverse cash on maintenance delete:', cashErr);
          }
        }
        return;
      }

      await deleteDoc(doc(db, 'maintenance_items', id));
      // حاول أيضاً حذف النسخ المتزامنة في المجموعات الأخرى
      try {
        const qPending = query(collection(db, 'maintenance_pending'), where('linkedId', '==', id), limit(1));
        const snapPending = await getDocs(qPending);
        if (snapPending.docs[0]?.id) await deleteDoc(doc(db, 'maintenance_pending', snapPending.docs[0].id));
      } catch {}
      try {
        const qDone = query(collection(db, 'maintenance_done'), where('linkedId', '==', id), limit(1));
        const snapDone = await getDocs(qDone);
        if (snapDone.docs[0]?.id) await deleteDoc(doc(db, 'maintenance_done', snapDone.docs[0].id));
      } catch {}

      // تحديث الحالة محلياً
      setItems((prev) => {
        const next = prev.filter((i) => i.id !== id);
        try {
          if (user?.uid) {
            localStorage.setItem(
              maintenanceItemsCacheKey(user.uid),
              JSON.stringify(serializeMaintenanceItemsForCache(next))
            );
          }
        } catch {
          /* ignore */
        }
        computeProfit(next);
        return next;
      });

      // عكس تأثير الكاش إن لزم الأمر
      if (amountToReverse > 0) {
        try {
          const genericKey = `cashBalance_${user?.uid || 'default'}`;
          const shopKey = `cashBalance_${user?.uid || 'default'}_${shopIdCtx || 'main'}`;
          const saved = localStorage.getItem(shopKey) ?? localStorage.getItem(genericKey) ?? '0';
          const currentCash = parseFloat(saved || '0') || 0;
          const newCash = currentCash - amountToReverse;
          try { localStorage.setItem(genericKey, String(newCash)); } catch {}
          try { localStorage.setItem(shopKey, String(newCash)); } catch {}
          if (user?.uid) {
            try { await userDataService.updateUserData(user.uid, { cashBalance: newCash }); } catch {}
          }
          try {
            const shopId = (profile as any)?.shopId || shopIdCtx;
            if (shopId) {
              await updateDoc(doc(db, 'dashboardData', shopId), { cashBalance: newCash, lastUpdated: new Date().toISOString() } as any);
            }
          } catch {}
          try { window.dispatchEvent(new CustomEvent('cashBalanceChanged', { detail: { value: newCash } })); } catch {}
        } catch (cashErr) {
          console.warn('Failed to reverse cash on maintenance delete:', cashErr);
        }
      }
    } catch (e) {
      alert('حدث خطأ أثناء حذف عنصر الصيانة');
    } finally {
      setBusyItemId(null);
    }
  };

  const handleAddWaste = async () => {
    if (!user?.uid || !wasteAmount) return;
    try {
      const amountNum = Number(wasteAmount);
      const desc = `جهاز: ${wasteDevice} - عطل: ${wasteFault}`;

      if (maintenanceHold) {
        const wid = `local_waste_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
        appendMaintenanceQueue(user.uid, {
          t: 'wasteAdd',
          uid: user.uid,
          wid,
          data: {
            userId: user.uid,
            amount: amountNum,
            description: desc,
            note: desc,
            shopId: shopIdCtx ?? null,
            createdAt: MAINT_SERVER_TS,
          },
        });
        const row = {
          id: wid,
          userId: user.uid,
          amount: amountNum,
          description: desc,
          note: desc,
          shopId: shopIdCtx,
          createdAt: new Date(),
        };
        try {
          const raw = localStorage.getItem(maintenanceWasteCacheKey(user.uid));
          const arr = raw ? JSON.parse(raw) : [];
          const list = Array.isArray(arr) ? arr : [];
          list.unshift({
            ...row,
            createdAt: row.createdAt.toISOString(),
          });
          localStorage.setItem(maintenanceWasteCacheKey(user.uid), JSON.stringify(list));
        } catch {
          /* ignore */
        }
        setWasteHistory((prev) => [row, ...prev]);
        setMonthlyWaste((m) => {
          const now = new Date();
          const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
          return row.createdAt >= startOfMonth ? m + amountNum : m;
        });
        setWasteDialogOpen(false);
        setWasteDevice('');
        setWasteFault('');
        setWasteAmount('');
        setShowSuccessDialog(true);
        return;
      }

      await addDoc(collection(db, 'users', user.uid, 'maintenance_waste'), {
        userId: user.uid,
        amount: amountNum,
        description: desc,
        note: desc,
        createdAt: serverTimestamp(),
        shopId: shopIdCtx,
      });
      setWasteDialogOpen(false);
      setWasteDevice('');
      setWasteFault('');
      setWasteAmount('');
      fetchMonthlyWaste();
      fetchWasteHistory();
      setShowSuccessDialog(true);
    } catch (e) {
      console.error(e);
      alert('حدث خطأ أثناء إضافة إيصال الهوالك');
    }
  };

  const handleAddMaterialPurchase = async () => {
    if (!user?.uid) {
      alert('يرجى تسجيل الدخول أولاً قبل تسجيل شراء الخامات.');
      return;
    }
    const price = Number(materialPrice);
    if (!materialName.trim() || !price || price <= 0) {
      alert('يرجى إدخال اسم القطعة وسعر صحيح.');
      return;
    }
    if (!materialSource) {
      alert('اختر طريقة تسجيل الشراء (الدرج / المحافظ / بدون خصم).');
      return;
    }
    if (materialSource === 'wallet' && !materialWalletId) {
      alert('اختر المحفظة التي سيتم الخصم منها.');
      return;
    }
    setIsSavingMaterial(true);
    try {
      const sourceForStorage = materialSource === 'none' ? 'fawry' : materialSource;

      if (maintenanceHold) {
        const mid = `local_mat_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
        appendMaintenanceQueue(user.uid, {
          t: 'materialAdd',
          uid: user.uid,
          mid,
          data: {
            userId: user.uid,
            shopId: shopIdCtx || null,
            name: materialName.trim(),
            amount: price,
            notes: materialNotes.trim(),
            source: sourceForStorage,
            createdAt: MAINT_SERVER_TS,
          },
        });

        if (materialSource === 'cash') {
          try {
            const genericKey = `cashBalance_${user?.uid || 'default'}`;
            const shopKey = `cashBalance_${user?.uid || 'default'}_${shopIdCtx || 'main'}`;
            const saved = localStorage.getItem(shopKey) ?? localStorage.getItem(genericKey) ?? '0';
            const currentCash = parseFloat(saved || '0') || 0;
            const newCash = currentCash - price;
            try { localStorage.setItem(genericKey, String(newCash)); } catch {}
            try { localStorage.setItem(shopKey, String(newCash)); } catch {}
            try { window.dispatchEvent(new CustomEvent('cashBalanceChanged', { detail: { value: newCash } })); } catch {}
          } catch (e) {
            console.warn('فشل تحديث رصيد النقدية بعد شراء الخامات:', e);
          }
        }
        if (materialSource === 'wallet' && materialWalletId) {
          bumpLocalWalletBalance(user.uid, materialWalletId, -price);
        }

        const matRow = {
          id: mid,
          userId: user.uid,
          shopId: shopIdCtx || null,
          name: materialName.trim(),
          amount: price,
          notes: materialNotes.trim(),
          source: sourceForStorage,
          createdAt: new Date(),
        };
        try {
          const raw = localStorage.getItem(maintenanceMaterialsCacheKey(user.uid));
          const arr = raw ? JSON.parse(raw) : [];
          const list = Array.isArray(arr) ? arr : [];
          list.unshift({ ...matRow, createdAt: matRow.createdAt.toISOString() });
          localStorage.setItem(maintenanceMaterialsCacheKey(user.uid), JSON.stringify(list));
        } catch {
          /* ignore */
        }

        setMaterialName('');
        setMaterialPrice('');
        setMaterialNotes('');
        setMaterialSource(null);
        setMaterialWalletId('');
        setMaterialsDialogOpen(false);
        setShowSuccessDialog(true);
        return;
      }

      // تسجيل إيصال شراء الخامات أولاً
      await addDoc(collection(db, 'users', user.uid, 'maintenance_materials'), {
        userId: user.uid,
        shopId: shopIdCtx || null,
        name: materialName.trim(),
        amount: price,
        notes: materialNotes.trim(),
        source: sourceForStorage,
        createdAt: serverTimestamp(),
      });

      // تحديث رصيد النقدية يتم في الخلفية بدون تأخير الواجهة
      if (materialSource === 'cash') {
        (async () => {
          try {
            const genericKey = `cashBalance_${user?.uid || 'default'}`;
            const shopKey = `cashBalance_${user?.uid || 'default'}_${shopIdCtx || 'main'}`;
            const saved = localStorage.getItem(shopKey) ?? localStorage.getItem(genericKey) ?? '0';
            const currentCash = parseFloat(saved || '0') || 0;
            const newCash = currentCash - price;
            try { localStorage.setItem(genericKey, String(newCash)); } catch {}
            try { localStorage.setItem(shopKey, String(newCash)); } catch {}
            if (user?.uid) {
              try { await userDataService.updateUserData(user.uid, { cashBalance: newCash }); } catch {}
            }
            try {
              const shopId = (profile as any)?.shopId || shopIdCtx;
              if (shopId) {
                await updateDoc(doc(db, 'dashboardData', shopId), { cashBalance: newCash, lastUpdated: new Date().toISOString() } as any);
              }
            } catch {}
            try { window.dispatchEvent(new CustomEvent('cashBalanceChanged', { detail: { value: newCash } })); } catch {}
          } catch (e) {
            console.warn('فشل تحديث رصيد النقدية بعد شراء الخامات:', e);
          }
        })();
      }
      // خصم من المحفظة المختارة (walletBalances + dashboardData) مثل سلوك الأندرويد
      if (materialSource === 'wallet' && materialWalletId) {
        (async () => {
          try {
            const userId = user?.uid;
            if (!userId) return;
            const data = await userDataService.getUserData(userId);
            const balances: Record<string, number> = { ...((data as any)?.walletBalances || {}) };
            const prev = Number(balances[materialWalletId] || 0);
            const newVal = Math.max(0, prev - price);
            balances[materialWalletId] = newVal;
            await userDataService.updateUserData(userId, { walletBalances: balances });

            const shopId = (profile as any)?.shopId || shopIdCtx;
            if (shopId) {
              try {
                const snap = await getDocs(query(collection(db, 'dashboardData'), where('__name__', '==', shopId), limit(1)));
                const rec = snap.docs[0];
                if (rec) {
                  const dataDoc: any = rec.data();
                  const wb: Record<string, number> = { ...(dataDoc.walletBalances || {}) };
                  const prevDash = Number(wb[materialWalletId] || 0);
                  wb[materialWalletId] = Math.max(0, prevDash - price);
                  await updateDoc(doc(db, 'dashboardData', shopId), { walletBalances: wb, lastUpdated: new Date().toISOString() } as any);
                  try {
                    window.dispatchEvent(new CustomEvent('dashboard:external-update', {
                      detail: {
                        walletBalances: wb,
                        limitUpdate: {
                          walletId: materialWalletId,
                          amount: price,
                          type: 'withdraw',
                        },
                      }
                    }));
                  } catch {}
                }
              } catch (e) {
                console.warn('Failed to update dashboardData for maintenance wallet purchase:', e);
              }
            }
          } catch (e) {
            console.warn('فشل تحديث رصيد المحفظة بعد شراء الخامات:', e);
          }
        })();
      }

      setMaterialName('');
      setMaterialPrice('');
      setMaterialNotes('');
      setMaterialSource(null);
      setMaterialWalletId('');
      setMaterialsDialogOpen(false);
      setShowSuccessDialog(true);
    } catch (e) {
      console.error('Failed to add maintenance materials purchase:', e);
      alert('حدث خطأ أثناء تسجيل شراء الخامات. حاول مرة أخرى.');
    } finally {
      setIsSavingMaterial(false);
    }
  };

  const [searchQuery, setSearchQuery] = useState('');

  const normalizedSearch = searchQuery.trim().toLowerCase();

  const filterBySearch = (list: any[]) => {
    if (!normalizedSearch) return list;
    return list.filter((it) => {
      const name = String(it.customerName || '').toLowerCase();
      const phone = String(it.mobile || '');
      return name.includes(normalizedSearch) || phone.includes(normalizedSearch);
    });
  };

  const sortByNewest = (list: MaintenanceItem[]) => {
    return [...list].sort((a, b) => {
      const getDate = (it: MaintenanceItem) => {
        // في حالة "تم التصليح" نفضل تاريخ الإتمام، وإلا نستخدم تاريخ الإنشاء
        const base =
          (it.status === 'completed' && it.completedAt) ? it.completedAt : it.createdAt;
        return base ? new Date(base).getTime() : 0;
      };
      return getDate(b) - getDate(a);
    });
  };

  const inProgressItems = sortByNewest(
    filterBySearch(items.filter(it => it.status === 'in_progress'))
  );
  const waitingItems = sortByNewest(
    filterBySearch(items.filter(it => it.status === 'waiting_for_delivery'))
  );
  const completedItems = sortByNewest(
    filterBySearch(items.filter(it => it.status === 'completed'))
  );



